    async prepareActionPrompt(request: ActionPromptRequest): Promise<PreparedActionPrompt> {
        return this.request<PreparedActionPrompt>('prepareActionPrompt', [request])
    }

    async readFileAtCommit(request: ReadFileAtCommitRequest): Promise<HistoricalFileContent> {
        return this.request<HistoricalFileContent>('readFileAtCommit', [request])
    }

    async runSearchRegexpAgent(input: string, callback?: (event: AgentRunEvent) => void): Promise<string> {
        return this.requestWithAgentEvents<string>('runSearchRegexpAgent', [input], callback)
    }

    async startAction(request: ActionStartRequest): Promise<string> {
        return this.request<string>('startAction', [request])
    }

    async startUnattendedAction(request: ActionStartRequest): Promise<string> {
        return this.request<string>('startUnattendedAction', [request])
    }

    private async requestWithAgentEvents<T>(method: string, params: unknown[], onEvent?: (event: AgentRunEvent) => void): Promise<T> {
        if (!onEvent) return this.request<T>(method, params)

        const id = this.createRequestId()
        this.requestAgentEvents.set(id, onEvent)

        try {
            const result = await this.sendRequest<T>({ id, method, params })
            const runId = (result as { runId?: unknown }).runId
            if (typeof runId === 'string') this.runAgentEvents.set(runId, onEvent)

            return result
        } finally {
            this.requestAgentEvents.delete(id)
        }
    }

    private async request<T>(method: string, params: unknown[]): Promise<T> {
        return this.sendRequest<T>({ id: this.createRequestId(), method, params })
    }

    private async sendRequest<T>(request: RemoteControlRequest): Promise<T> {
        await this.ensureConnected()

        return new Promise<T>((resolve, reject) => {
            this.pending.set(request.id, { reject, resolve: resolve as (value: unknown) => void })
            this.requireSocket().send(JSON.stringify(request))
        })
    }

    private createRequestId() {
        const id = `remote-${this.nextId}`
        this.nextId += 1

        return id
    }

    private async ensureConnected() {
        if (this.retired) throw new RemoteControlConnectionError('Remote-control connection was replaced')
        if (this.socket?.readyState === SOCKET_OPEN_STATE) return
        if (this.connectPromise) return this.connectPromise

        this.socket = new WebSocket(this.endpoint)
        this.socket.addEventListener('message', (event) => this.handleMessage(event))
        this.socket.addEventListener('close', () => this.handleClose())
        this.socket.addEventListener('error', () => this.handleClose())
        this.connectPromise = new Promise((resolve, reject) => {
            const handleOpen = () => {
                this.connectPromise = null
                resolve()
                for (const listener of this.connectionListeners) listener(true)
                void this.restoreActionRunSubscriptions()
                void this.restoreCodexRateLimitSubscriptions()
                void this.restoreProjectWatchSubscriptions()
                void this.restoreWorktreeSubscription()
            }
            const handleError = () => {
                this.connectPromise = null
                reject(new RemoteControlConnectionError('Remote-control connection failed'))
            }

            this.requireSocket().addEventListener('open', handleOpen, { once: true })
            this.requireSocket().addEventListener('error', handleError, { once: true })
        })

        return this.connectPromise
    }

    private handleMessage(event: MessageEvent) {
        const message = JSON.parse(String(event.data)) as RemoteControlResponse | RemoteControlEvent
        if (isResponse(message)) {
            this.handleResponse(message)
            return
        }

        this.handleEvent(message)
    }

    private handleResponse(response: RemoteControlResponse) {
        const pending = this.pending.get(response.id)
        if (!pending) return

        this.pending.delete(response.id)
        if (response.error) {
            pending.reject(new Error(response.error.message))
            return
        }

        pending.resolve(response.result)
    }

    private handleEvent(message: RemoteControlEvent) {
        if (message.event === 'actionRun') {
            this.handleActionRunEvent(message.payload as ActionRunPayload)
            return
        }
        if (message.event === 'codexRateLimits') {
            this.handleCodexRateLimitsEvent(message.payload as CodexRateLimitsPayload)
            return
        }
        if (message.event === 'watchProject') {
            this.handleWatchProjectEvent(message.payload as WatchProjectPayload)
            return
        }
        if (message.event === 'worktreesChanged') {
            this.handleWorktreesChangedEvent(message.payload as WorktreesChangedPayload)
            return
        }
        if (message.event === 'mergeConflictSessionChanged') {
            this.handleMergeConflictSessionChangedEvent(message.payload as MergeConflictSessionChangedPayload)
            return
        }

        if (message.event === 'agentRun') this.handleAgentRunEvent(message.payload as AgentRunPayload)
    }

    private handleActionRunEvent(payload: ActionRunPayload) {
        const callback = this.actionRunCallbacks.get(payload.subscriptionId)
            ?? this.requestActionRunEvents.get(payload.requestId)
        callback?.(payload.event)
    }

    private handleCodexRateLimitsEvent(payload: CodexRateLimitsPayload) {
        const callback = this.codexRateLimitCallbacks.get(payload.subscriptionId)
            ?? this.requestCodexRateLimitEvents.get(payload.requestId)
        callback?.(payload.snapshot)
    }

    private async restoreActionRunSubscriptions() {
        const pendingCallbacks = new Set(this.requestActionRunEvents.values())
        const callbacks = [...this.actionRunListeners].filter((callback) => !pendingCallbacks.has(callback))
        await Promise.allSettled(callbacks.map((callback) => this.subscribeActionRun(callback, true)))
    }

    private async subscribeActionRun(callback: (event: ActionRunEvent) => void, recover: boolean) {
        const id = this.createRequestId()
        this.requestActionRunEvents.set(id, callback)
        try {
            const result = await this.sendRequest<{ subscriptionId: string }>({
                id,
                method: 'onActionRun',
                params: [],
            })
            if (!this.actionRunListeners.has(callback)) {
                await this.request('unsubscribe', [result.subscriptionId])
                return
            }
            this.actionRunSubscriptions.set(callback, result.subscriptionId)
            this.actionRunCallbacks.set(result.subscriptionId, callback)
            if (!recover) return
            const events = await this.loadActiveActionRunEvents()
            for (const event of events) callback(event)
        } finally {
            this.requestActionRunEvents.delete(id)
        }
    }

    private async restoreCodexRateLimitSubscriptions() {
        const pendingCallbacks = new Set(this.requestCodexRateLimitEvents.values())
        const callbacks = [...this.codexRateLimitListeners].filter((callback) => !pendingCallbacks.has(callback))
        await Promise.allSettled(callbacks.map((callback) => this.subscribeCodexRateLimits(callback)))
    }

    private async restoreProjectWatchSubscriptions() {
        const subscriptions = [...this.watchSubscriptions].filter((subscription) => (
            !subscription.subscribing && subscription.serverSubscriptionId === null
        ))
        await Promise.allSettled(subscriptions.map((subscription) => this.subscribeProjectWatch(subscription, true)))
    }

    private async restoreWorktreeSubscription() {
        await this.subscribeWorktreesChanged()
    }

    private async subscribeProjectWatch(subscription: ProjectWatchSubscription, restored: boolean) {
        if (!this.watchSubscriptions.has(subscription) || subscription.subscribing || subscription.serverSubscriptionId) return

        const id = this.createRequestId()
        subscription.subscribing = true
        this.requestWatchEvents.set(id, subscription)
        try {
            const result = await this.sendRequest<{ subscriptionId: string }>({
                id,
                method: 'watchProject',
                params: [subscription.project],
            })
            if (!this.watchSubscriptions.has(subscription)) {
                await this.request('unsubscribe', [result.subscriptionId])
                return
            }

            subscription.serverSubscriptionId = result.subscriptionId
            this.watchCallbacks.set(result.subscriptionId, subscription)
            if (restored) subscription.onRestored()
        } finally {
            subscription.subscribing = false
            this.requestWatchEvents.delete(id)
        }
    }

    private async subscribeCodexRateLimits(callback: (snapshot: CodexRateLimitSnapshot) => void) {
        const id = this.createRequestId()
        this.requestCodexRateLimitEvents.set(id, callback)
        try {
            const result = await this.sendRequest<{ subscriptionId: string }>({
                id,
                method: 'onCodexRateLimits',
                params: [],
            })
            if (!this.codexRateLimitListeners.has(callback)) {
                await this.request('unsubscribe', [result.subscriptionId])
                return
            }
            this.codexRateLimitSubscriptions.set(callback, result.subscriptionId)
            this.codexRateLimitCallbacks.set(result.subscriptionId, callback)
        } finally {
            this.requestCodexRateLimitEvents.delete(id)
        }
    }

    private async subscribeWorktreesChanged() {
        if (this.worktreeListenerCount === 0 || this.worktreeRequestId || this.worktreeServerSubscriptionId) return

        const id = this.createRequestId()
        this.worktreeRequestId = id
        try {
            const result = await this.sendRequest<{ subscriptionId: string }>({
                id,
                method: 'onWorktreesChanged',
                params: [],
            })
            if (this.worktreeRequestId !== id || this.worktreeListenerCount === 0) {
                await this.request('unsubscribe', [result.subscriptionId])
                return
            }

            this.worktreeRequestId = null
            this.worktreeServerSubscriptionId = result.subscriptionId
        } finally {
            if (this.worktreeRequestId === id) this.worktreeRequestId = null
        }
    }

    private handleWatchProjectEvent(payload: WatchProjectPayload) {
        const subscription = this.watchCallbacks.get(payload.subscriptionId)
            ?? this.requestWatchEvents.get(payload.requestId)
        if ('error' in payload.event) {
            subscription?.onError(new Error(payload.event.error))
            return
        }

        subscription?.onChange(payload.event)
    }

    private handleWorktreesChangedEvent(payload: WorktreesChangedPayload) {
        const matchesRequest = payload.requestId === this.worktreeRequestId
        const matchesSubscription = payload.subscriptionId === this.worktreeServerSubscriptionId
        if (!matchesRequest && !matchesSubscription) return

        this.worktreeEvents.dispatchEvent(new CustomEvent(WORKTREES_CHANGED_EVENT, { detail: payload.state }))
    }

    private handleMergeConflictSessionChangedEvent(payload: MergeConflictSessionChangedPayload) {
        const callback = this.mergeConflictCallbacks.get(payload.subscriptionId)
            ?? this.requestMergeConflictEvents.get(payload.requestId)
        callback?.(payload.session)
    }

    private handleAgentRunEvent(payload: AgentRunPayload) {
        const callback = this.requestAgentEvents.get(payload.requestId) ?? this.runAgentEvents.get(payload.event.runId)
        callback?.(payload.event)
        if (payload.event.type === 'closed') this.runAgentEvents.delete(payload.event.runId)
    }

    private handleClose() {
        const error = new RemoteControlConnectionError('Remote-control connection closed')
        for (const listener of this.connectionListeners) listener(false)
        for (const pending of this.pending.values()) pending.reject(error)
        this.pending.clear()
        this.actionRunCallbacks.clear()
        this.actionRunSubscriptions.clear()
        this.codexRateLimitCallbacks.clear()
        this.codexRateLimitSubscriptions.clear()
        this.mergeConflictCallbacks.clear()
        this.requestAgentEvents.clear()
        this.requestActionRunEvents.clear()
        this.requestCodexRateLimitEvents.clear()
        this.requestMergeConflictEvents.clear()
        this.requestWatchEvents.clear()
        this.runAgentEvents.clear()
        this.watchCallbacks.clear()
        for (const subscription of this.watchSubscriptions) {
            subscription.serverSubscriptionId = null
            subscription.subscribing = false
        }
        this.worktreeRequestId = null
        this.worktreeServerSubscriptionId = null
        this.connectPromise = null
        this.socket = null
    }

    private requireSocket() {
        if (!this.socket) throw new Error('Remote-control socket is not connected')

        return this.socket
    }
}

import type { RemoteControlConnectionSettings } from '../../data/remote_control_connection'
import { configureRemoteControlConnection, readRemoteControlConnection } from '../../data/remote_control_connection'
import { setActionBridgeOverride } from '../../data/electron_action_bridge'
import { setCodexRuntimeBridgeOverride } from '../../data/electron_codex_runtime_bridge'
import { agentCapabilitiesService } from '../agents/agent_capabilities_service'
import { actionRunRegistry } from '../actions/action_run_registry'
import { codexRateLimitService } from '../agents/codex_rate_limit_service'
import { readDesktopConfigFromBridge } from '../config/config_persistence'
import { configService } from '../config/config_service'
import { setDesktopConfigTransportOverride } from '../config/desktop_config_transport'
import { getService, register } from '../service_injector'
import {
    isRemoteControlConnectionError,
    RemoteControlConnectionError,
    RemoteControlStorageService,
} from './remote_control_storage_service'

export type RemoteConnectionStatus = 'connecting' | 'disconnected' | 'ready' | 'reconnecting'

export interface RemoteConnectionSnapshot {
    endpoint: string | null
    errorMessage: string | null
    status: RemoteConnectionStatus
}

export interface RemoteConnectionServiceDependencies {
    activate(storage: RemoteControlStorageService): Promise<void>
    clearActivation(): void
    createStorage(): RemoteControlStorageService
    replaceProjectStorage(storage: RemoteControlStorageService): void
}

const INITIAL_RECONNECT_DELAY_MS = 1_000
const MAX_RECONNECT_DELAY_MS = 30_000
const INITIAL_SNAPSHOT: RemoteConnectionSnapshot = { endpoint: null, errorMessage: null, status: 'disconnected' }

async function activateRemoteStorage(storage: RemoteControlStorageService) {
    try {
        const desktopConfig = await storage.loadDesktopConfig()
        configService.replaceDesktopConfig(desktopConfig)
        setActionBridgeOverride(storage)
        setCodexRuntimeBridgeOverride(storage)
        setDesktopConfigTransportOverride(storage)
        codexRateLimitService.start()
        actionRunRegistry.start()
        await agentCapabilitiesService.reload()
    } catch (error) {
        if (isRemoteControlConnectionError(error)) throw error
        const message = error instanceof Error ? error.message : 'Unknown remote desktop config error'
        throw new Error(`Remote desktop config load failed: ${message}`, { cause: error })
    }
}

function clearRemoteActivation() {
    setActionBridgeOverride(null)
    setCodexRuntimeBridgeOverride(null)
    setDesktopConfigTransportOverride(null)
    if (!configService.isInitialized()) return

    const desktopConfig = readDesktopConfigFromBridge()
    if (desktopConfig) {
        configService.replaceDesktopConfig(desktopConfig)

        return
    }
    if (configService.hasDesktopConfig()) configService.clearDesktopConfig()
}

const DEFAULT_DEPENDENCIES: RemoteConnectionServiceDependencies = {
    activate: activateRemoteStorage,
    clearActivation: clearRemoteActivation,
    createStorage: () => new RemoteControlStorageService(),
    replaceProjectStorage: (storage) => getService<{ replaceRemoteStorage(storage: RemoteControlStorageService): void }>('dataService')
        .replaceRemoteStorage(storage),
}

function sameSettings(left: RemoteControlConnectionSettings | null, right: RemoteControlConnectionSettings) {
    return left?.endpoint === right.endpoint
}

/** Owns browser-to-desktop connection state, activation order, and reconnection. */
export class RemoteConnectionService extends EventTarget {
    private activeStorage: RemoteControlStorageService | null = null
    private connectingStorage: RemoteControlStorageService | null = null
    private connectionPromise: Promise<RemoteControlStorageService | null> | null = null
    private readonly dependencies: RemoteConnectionServiceDependencies
    private lifecycleId = 0
    private projectFlowHandled = false
    private projectStorageActive = false
    private reconnectDelayMs = INITIAL_RECONNECT_DELAY_MS
    private retryResolve: (() => void) | null = null
    private retryTimeout: number | null = null
    private settings: RemoteControlConnectionSettings | null = null
    private snapshot = INITIAL_SNAPSHOT
    private unsubscribeConnection: (() => void) | null = null

    constructor(dependencies: RemoteConnectionServiceDependencies = DEFAULT_DEPENDENCIES) {
        super()
        this.dependencies = dependencies
        register('remoteConnectionService', this)
    }

    readonly getSnapshot = () => this.snapshot

    readonly subscribe = (listener: () => void) => {
        this.addEventListener('changed', listener)

        return () => this.removeEventListener('changed', listener)
    }

    async connect(settings: RemoteControlConnectionSettings): Promise<RemoteControlStorageService> {
        return this.startConnection(settings)
    }

    connectExisting(storage: RemoteControlStorageService) {
        return this.startConnection(storage.getConnectionSettings(), storage)
    }

    connectStored() {
        return this.connect(readRemoteControlConnection())
    }

    private async startConnection(
        settings: RemoteControlConnectionSettings,
        initialStorage?: RemoteControlStorageService,
    ): Promise<RemoteControlStorageService> {
        if (sameSettings(this.settings, settings)) {
            if (this.snapshot.status === 'ready' && this.activeStorage) return this.activeStorage
            if (this.connectionPromise) {
                const storage = await this.connectionPromise
                if (storage) return storage
            }
        }

        this.lifecycleId += 1
        const lifecycleId = this.lifecycleId
        this.stopCurrentConnection()
        this.projectFlowHandled = false
        this.settings = settings
        this.publish({ endpoint: settings.endpoint, errorMessage: null, status: 'connecting' })
        const connectionPromise = this.connectOnce(settings, lifecycleId, false, initialStorage)
        this.connectionPromise = connectionPromise
        try {
            const storage = await connectionPromise
            if (!storage) throw new RemoteControlConnectionError('Remote-control connection cancelled')
            configureRemoteControlConnection(settings)

            return storage
        } finally {
            if (this.connectionPromise === connectionPromise) this.connectionPromise = null
        }
    }

    disconnect() {
        this.lifecycleId += 1
        this.projectStorageActive = false
        this.projectFlowHandled = false
        this.stopCurrentConnection()
        this.settings = null
        this.dependencies.clearActivation()
        this.publish(INITIAL_SNAPSHOT)
    }

    isProjectStorageActive() {
        return this.projectStorageActive
    }

    setProjectStorageActive(active: boolean) {
        this.projectStorageActive = active
        if (active) this.projectFlowHandled = true
    }

    async runProjectOpenFlow(operation: () => Promise<void>) {
        if (this.projectStorageActive || this.projectFlowHandled) return

        this.projectFlowHandled = true
        await operation()
    }

    private async connectOnce(
        settings: RemoteControlConnectionSettings,
        lifecycleId: number,
        reconnecting: boolean,
        initialStorage?: RemoteControlStorageService,
    ): Promise<RemoteControlStorageService | null> {
        const storage = initialStorage ?? this.dependencies.createStorage()
        if (!initialStorage) storage.init(settings)
        this.connectingStorage = storage
        let connectionClosed = false
        const unsubscribe = storage.onConnectionChanged((connected) => {
            if (connected) return
            connectionClosed = true
            if (this.activeStorage === storage && this.snapshot.status === 'ready') this.startReconnecting(lifecycleId)
        })

        try {
            await storage.connect()
            if (connectionClosed) throw new RemoteControlConnectionError('Remote-control connection closed')
            await this.dependencies.activate(storage)
            if (connectionClosed) throw new RemoteControlConnectionError('Remote-control connection closed')
            if (lifecycleId !== this.lifecycleId) {
                if (this.connectingStorage === storage) this.connectingStorage = null
                storage.retire()

                return null
            }

            this.unsubscribeConnection?.()
            this.unsubscribeConnection = unsubscribe
            this.activeStorage = storage
            if (this.connectingStorage === storage) this.connectingStorage = null
            this.reconnectDelayMs = INITIAL_RECONNECT_DELAY_MS
            if (reconnecting && this.projectStorageActive) this.dependencies.replaceProjectStorage(storage)
            this.publish({ endpoint: settings.endpoint, errorMessage: null, status: 'ready' })

            return storage
        } catch (error) {
            if (this.connectingStorage === storage) this.connectingStorage = null
            unsubscribe()
            storage.retire()
            if (lifecycleId !== this.lifecycleId) return null
            this.dependencies.clearActivation()
            const errorMessage = error instanceof Error ? error.message : 'Remote-control connection failed'
            if (!reconnecting) this.publish({ endpoint: settings.endpoint, errorMessage, status: 'disconnected' })
            throw error
        }
    }

    private startReconnecting(lifecycleId: number) {
        if (lifecycleId !== this.lifecycleId || !this.settings) return

        this.unsubscribeConnection?.()
        this.unsubscribeConnection = null
        const staleStorage = this.activeStorage
        this.activeStorage = null
        staleStorage?.retire()
        this.dependencies.clearActivation()
        this.publish({ endpoint: this.settings.endpoint, errorMessage: null, status: 'reconnecting' })
        const connectionPromise = this.reconnect(this.settings, lifecycleId)
        this.connectionPromise = connectionPromise
        void connectionPromise.finally(() => {
            if (this.connectionPromise === connectionPromise) this.connectionPromise = null
        })
    }

    private async reconnect(
        settings: RemoteControlConnectionSettings,
        lifecycleId: number,
    ): Promise<RemoteControlStorageService | null> {
        let delayMs = 0
        while (lifecycleId === this.lifecycleId) {
            if (delayMs > 0) await this.waitForRetry(delayMs)
            if (lifecycleId !== this.lifecycleId) return null

            try {
                return await this.connectOnce(settings, lifecycleId, true)
            } catch (error) {
                if (lifecycleId !== this.lifecycleId) return null
                const errorMessage = error instanceof Error ? error.message : 'Remote-control reconnection failed'
                this.publish({ endpoint: settings.endpoint, errorMessage, status: 'reconnecting' })
                delayMs = this.reconnectDelayMs
                this.reconnectDelayMs = Math.min(this.reconnectDelayMs * 2, MAX_RECONNECT_DELAY_MS)
            }
        }

        return null
    }

    private waitForRetry(delayMs: number) {
        return new Promise<void>((resolve) => {
            this.retryResolve = resolve
            this.retryTimeout = window.setTimeout(() => {
                this.retryResolve = null
                this.retryTimeout = null
                resolve()
            }, delayMs)
        })
    }

    private stopCurrentConnection() {
        if (this.retryTimeout !== null) window.clearTimeout(this.retryTimeout)
        this.retryTimeout = null
        this.retryResolve?.()
        this.retryResolve = null
        this.unsubscribeConnection?.()
        this.unsubscribeConnection = null
        this.connectingStorage?.retire()
        this.connectingStorage = null
        this.activeStorage?.retire()
        this.activeStorage = null
        this.connectionPromise = null
    }

    private publish(snapshot: RemoteConnectionSnapshot) {
        if (
            this.snapshot.endpoint === snapshot.endpoint
            && this.snapshot.errorMessage === snapshot.errorMessage
            && this.snapshot.status === snapshot.status
        ) return

        this.snapshot = snapshot
        this.dispatchEvent(new Event('changed'))
    }
}

export const remoteConnectionService = new RemoteConnectionService()

